   147→        public bool InsertCode(Address address, in ValueHash256 codeHash, ReadOnlyMemory<byte> code, IReleaseSpec spec, bool isGenesis = false)
   148→        {
   149→            bool inserted = false;
   150→
   151→            // Don't reinsert if already inserted. This can be the case when the same
   152→            // code is used by multiple deployments. Either from factory contracts (e.g. LPs)
   153→            // or people copy and pasting popular contracts
   154→            if (!_codeInsertFilter.Get(codeHash))
   155→            {
   156→                if (_codeBatch is null)
   157→                {
   158→                    _codeBatch = new(Hash256AsKeyComparer.Instance);
   159→                    _codeBatchAlternate = _codeBatch.GetAlternateLookup<ValueHash256>();
   160→                }
   161→                if (MemoryMarshal.TryGetArray(code, out ArraySegment<byte> codeArray)
   162→                        && codeArray.Offset == 0
   163→                        && codeArray.Count == code.Length)
   164→                {
   165→                    _codeBatchAlternate[codeHash] = codeArray.Array;
   166→                }
   167→                else
   168→                {
   169→                    _codeBatchAlternate[codeHash] = code.ToArray();
   170→                }
   171→
   172→                _codeInsertFilter.Set(codeHash);
   173→                inserted = true;
   174→            }
   175→
   176→            Account? account = GetThroughCache(address) ?? ThrowIfNull(address);
   177→            if (account.CodeHash.ValueHash256 != codeHash)
   178→            {
   179→                _needsStateRootUpdate = true;
   180→                if (_logger.IsDebug) Debug(address, codeHash, account);
   181→                Account changedAccount = account.WithChangedCodeHash((Hash256)codeHash);
   182→
   183→                PushUpdate(address, changedAccount);
   184→            }
   185→            else if (spec.IsEip158Enabled && !isGenesis)
   186→            {
   187→                if (_logger.IsTrace) Trace(address);
   188→                if (account.IsEmpty)
   189→                {
   190→                    PushTouch(address, account, spec, account.Balance.IsZero);
   191→                }
   192→            }
   193→
   194→            return inserted;
   195→
   196→            [MethodImpl(MethodImplOptions.NoInlining)]
   197→            void Debug(Address address, in ValueHash256 codeHash, Account account)
   198→                => _logger.Debug($"Update {address} C {account.CodeHash} -> {codeHash}");
   199→
   200→            [MethodImpl(MethodImplOptions.NoInlining)]
   201→            void Trace(Address address) => _logger.Trace($"Touch {address} (code hash)");
   202→
   203→            [DoesNotReturn, StackTraceHidden]
   204→            static Account ThrowIfNull(Address address)
   205→                => throw new InvalidOperationException($"Account {address} is null when updating code hash");
   206→        }
