   399→        /// <summary>
   400→        /// Restores the <see cref="StateProvider"/> to a prior state snapshot.
   401→        /// Rolls back any changes recorded after the specified <paramref name="snapshot"/> index,
   402→        /// while preserving lightweight cache-only entries.
   403→        /// </summary>
   404→        /// <param name="snapshot">Zero-based index representing the position in the change log to restore to.
   405→        /// Must be between 0 and the current last change index.</param>
   406→        /// <exception cref="InvalidOperationException">
   407→        /// Thrown if <paramref name="snapshot"/> is beyond the current position,
   408→        /// or if internal consistency checks fail during rollback.</exception>
   409→        public void Restore(int snapshot)
   410→        {
   411→            int lastIndex = _changes.Count - 1;
   412→            if (snapshot > lastIndex) ThrowCannotRestore(lastIndex, snapshot);
   413→            if (_logger.IsTrace) Trace(snapshot);
   414→            // No-op if already at the desired snapshot
   415→            if (snapshot == lastIndex) return;
   416→
   417→            int stepsBack = lastIndex - snapshot;
   418→            // Reserve capacity up‐front (avoid grows)
   419→            if (_keptInCache.Capacity < stepsBack)
   420→                _keptInCache.Capacity = stepsBack;
   421→
   422→            ReadOnlySpan<Change> changes = CollectionsMarshal.AsSpan(_changes);
   423→            // Roll back each change from newest down to target
   424→            for (int i = 0; i < stepsBack; i++)
   425→            {
   426→                int nextPosition = lastIndex - i;
   427→                ref readonly Change change = ref changes[nextPosition];
   428→                Stack<int> stack = _intraTxCache[change!.Address];
   429→
   430→                int actualPosition = stack.Pop();
   431→                if (actualPosition != nextPosition) ThrowUnexpectedPosition(lastIndex, i, actualPosition);
   432→
   433→                if (stack.Count == 0)
   434→                {
   435→                    if (change.ChangeType == ChangeType.JustCache)
   436→                    {
   437→                        // Keep if was caching entry
   438→                        _keptInCache.Add(change);
   439→                    }
   440→                    else
   441→                    {
   442→                        // Remove address entry entirely if no more changes
   443→                        _intraTxCache.Remove(change.Address);
   444→                    }
   445→                }
   446→            }
   447→
   448→            ReadOnlySpan<Change> keepInCache = CollectionsMarshal.AsSpan(_keptInCache);
   449→            // Truncate the change log to the restore point
   450→            CollectionsMarshal.SetCount(_changes, snapshot + 1);
   451→
   452→            // Re-append any cache-only entries, updating their positions
   453→            foreach (ref readonly Change kept in keepInCache)
   454→            {
   455→                snapshot++;
   456→                _changes.Add(kept);
   457→                _intraTxCache[kept.Address].Push(snapshot);
   458→            }
   459→            _keptInCache.Clear();
   460→
   461→            // Local helpers to keep cold code from throws and string interpolation out of hot code.
   462→            [MethodImpl(MethodImplOptions.NoInlining)]
   463→            void Trace(int snap) => _logger.Trace($"Restoring state snapshot {snap}");
   464→
   465→            [DoesNotReturn, StackTraceHidden]
   466→            static void ThrowCannotRestore(int current, int snap)
   467→                => throw new InvalidOperationException($"{nameof(StateProvider)} tried to restore snapshot {snap} beyond current position {current}");
   468→
   469→            [DoesNotReturn, StackTraceHidden]
   470→            static void ThrowUnexpectedPosition(int current, int step, int actual)
   471→                => throw new InvalidOperationException($"Expected actual position {actual} to be equal to {current} - {step}");
   472→        }
   473→
   474→        public void CreateAccount(Address address, in UInt256 balance, in UInt256 nonce = default)
   475→        {
   476→            _needsStateRootUpdate = true;
   477→            if (_logger.IsTrace) Trace(address, balance, nonce);
   478→
   479→            Account account = (balance.IsZero && nonce.IsZero) ? Account.TotallyEmpty : new Account(nonce, balance);
   480→            PushNew(address, account);
   481→
   482→            [MethodImpl(MethodImplOptions.NoInlining)]
   483→            void Trace(Address address, in UInt256 balance, in UInt256 nonce)
   484→                => _logger.Trace($"Creating account: {address} with balance {balance.ToHexString(skipLeadingZeros: true)} and nonce {nonce.ToHexString(skipLeadingZeros: true)}");
   485→        }
   486→
   487→        public void CreateAccountIfNotExists(Address address, in UInt256 balance, in UInt256 nonce = default)
   488→        {
   489→            if (!AccountExists(address))
   490→            {
   491→                CreateAccount(address, balance, nonce);
   492→            }
   493→        }
   494→
   495→        public bool AddToBalanceAndCreateIfNotExists(Address address, in UInt256 balance, IReleaseSpec spec)
   496→        {
   497→            if (AccountExists(address))
   498→            {
   499→                AddToBalance(address, balance, spec);
   500→                return false;
   501→            }
   502→            else
   503→            {
   504→                CreateAccount(address, balance);
   505→                return true;
   506→            }
   507→        }
   508→
   509→        public void Commit(IReleaseSpec releaseSpec, bool commitRoots, bool isGenesis)
   510→            => Commit(releaseSpec, NullStateTracer.Instance, commitRoots, isGenesis);
   511→
   512→        public void Commit(IReleaseSpec releaseSpec, IWorldStateTracer stateTracer, bool commitRoots, bool isGenesis)
   513→        {
   514→            Task codeFlushTask = !commitRoots || _codeBatch is null || _codeBatch.Count == 0
   515→                ? Task.CompletedTask
   516→                : CommitCodeAsync();
   517→
   518→            bool isTracing = _logger.IsTrace;
   519→            int stepsBack = _changes.Count - 1;
   520→            if (stepsBack < 0)
   521→            {
   522→                if (isTracing) TraceNoChanges();
   523→                if (commitRoots)
   524→                {
   525→                    FlushToTree();
   526→                }
   527→                return;
   528→            }
   529→
   530→            if (isTracing) TraceCommit(stepsBack);
   531→            if (_changes[stepsBack].IsNull)
   532→            {
   533→                ThrowStartOfCommitIsNull(stepsBack);
   534→            }
   535→
   536→            Dictionary<AddressAsKey, ChangeTrace>? trace = !stateTracer.IsTracingState ? null : [];
   537→
   538→            ReadOnlySpan<Change> changes = CollectionsMarshal.AsSpan(_changes);
   539→            for (int i = 0; i <= stepsBack; i++)
   540→            {
   541→                ref readonly Change change = ref changes[stepsBack - i];
   542→                if (trace is null && change!.ChangeType == ChangeType.JustCache)
   543→                {
   544→                    continue;
   545→                }
   546→
   547→                if (_committedThisRound.Contains(change!.Address))
   548→                {
   549→                    if (change.ChangeType == ChangeType.JustCache)
   550→                    {
   551→                        trace?.UpdateTrace(change.Address, change.Account);
   552→                    }
   553→
   554→                    continue;
   555→                }
   556→
   557→                // because it was not committed yet it means that the just cache is the only state (so it was read only)
   558→                if (trace is not null && change.ChangeType == ChangeType.JustCache)
   559→                {
   560→                    _nullAccountReads.Add(change.Address);
   561→                    continue;
   562→                }
   563→
   564→                Stack<int> stack = _intraTxCache[change.Address];
   565→                int forAssertion = stack.Pop();
   566→                if (forAssertion != stepsBack - i)
   567→                {
   568→                    ThrowUnexpectedPosition(stepsBack, i, forAssertion);
   569→                }
   570→
   571→                _committedThisRound.Add(change.Address);
   572→
   573→                switch (change.ChangeType)
   574→                {
   575→                    case ChangeType.JustCache:
   576→                        break;
   577→                    case ChangeType.Touch:
   578→                    case ChangeType.Update:
   579→                        {
   580→                            if (releaseSpec.IsEip158Enabled && change.Account.IsEmpty && !isGenesis)
   581→                            {
   582→                                if (isTracing) TraceRemoveEmpty(change);
   583→                                SetState(change.Address, null);
   584→                                trace?.AddToTrace(change.Address, null);
   585→                            }
   586→                            else
   587→                            {
   588→                                if (isTracing) TraceUpdate(change);
   589→                                SetState(change.Address, change.Account);
   590→                                trace?.AddToTrace(change.Address, change.Account);
   591→                            }
   592→
   593→                            break;
   594→                        }
   595→                    case ChangeType.New:
   596→                        {
   597→                            if (!releaseSpec.IsEip158Enabled || !change.Account.IsEmpty || isGenesis)
   598→                            {
   599→                                if (isTracing) TraceCreate(change);
   600→                                SetState(change.Address, change.Account);
   601→                                trace?.AddToTrace(change.Address, change.Account);
   602→                            }
   603→
   604→                            break;
   605→                        }
   606→                    case ChangeType.Delete:
   607→                        {
   608→                            if (isTracing) TraceRemove(change);
   609→                            bool wasItCreatedNow = false;
   610→                            while (stack.Count > 0)
   611→                            {
   612→                                int previousOne = stack.Pop();
   613→                                wasItCreatedNow |= _changes[previousOne].ChangeType == ChangeType.New;
   614→                                if (wasItCreatedNow)
   615→                                {
   616→                                    break;
   617→                                }
   618→                            }
   619→
   620→                            if (!wasItCreatedNow)
   621→                            {
   622→                                SetState(change.Address, null);
   623→                                trace?.AddToTrace(change.Address, null);
   624→                            }
   625→
   626→                            break;
   627→                        }
   628→                    default:
   629→                        ThrowUnknownChangeType();
   630→                        break;
   631→                }
   632→            }
   633→
   634→            trace?.ReportStateTrace(stateTracer, _nullAccountReads, this);
   635→
   636→            _changes.Clear();
   637→            _committedThisRound.Clear();
   638→            _nullAccountReads.Clear();
   639→            _intraTxCache.Clear();
   640→
   641→            if (commitRoots)
   642→            {
   643→                FlushToTree();
   644→            }
   645→
   646→            codeFlushTask.GetAwaiter().GetResult();
   647→
   648→            Task CommitCodeAsync()
   649→            {
   650→                Dictionary<Hash256AsKey, byte[]> dict = Interlocked.Exchange(ref _codeBatch, null);
   651→                if (dict is null) return Task.CompletedTask;
   652→                _codeBatchAlternate = default;
   653→
   654→                return Task.Run(() =>
   655→                {
   656→                    using (var batch = _codeDb.StartWriteBatch())
   657→                    {
   658→                        // Insert ordered for improved performance
   659→                        foreach (var kvp in dict.OrderBy(static kvp => kvp.Key))
   660→                        {
   661→                            batch.PutSpan(kvp.Key.Value.Bytes, kvp.Value);
   662→                        }
   663→                    }
   664→
   665→                    // Reuse Dictionary if not already re-initialized
   666→                    dict.Clear();
   667→                    if (Interlocked.CompareExchange(ref _codeBatch, dict, null) is null)
   668→                    {
   669→                        _codeBatchAlternate = _codeBatch.GetAlternateLookup<ValueHash256>();
   670→                    }
   671→                });
   672→            }
   673→
   674→            [MethodImpl(MethodImplOptions.NoInlining)]
   675→            void TraceCommit(int currentPosition) => _logger.Trace($"Committing state changes (at {currentPosition})");
   676→
   677→            [MethodImpl(MethodImplOptions.NoInlining)]
   678→            void TraceNoChanges() => _logger.Trace("No state changes to commit");
   679→
   680→            [MethodImpl(MethodImplOptions.NoInlining)]
   681→            void TraceRemove(in Change change) => _logger.Trace($"Commit remove {change.Address}");
   682→
   683→            [MethodImpl(MethodImplOptions.NoInlining)]
   684→            void TraceCreate(in Change change)
   685→                => _logger.Trace($"Commit create {change.Address} B = {change.Account.Balance.ToHexString(skipLeadingZeros: true)} N = {change.Account.Nonce.ToHexString(skipLeadingZeros: true)}");
   686→
   687→            [MethodImpl(MethodImplOptions.NoInlining)]
   688→            void TraceUpdate(in Change change)
   689→                => _logger.Trace($"Commit update {change.Address} B = {change.Account.Balance.ToHexString(skipLeadingZeros: true)} N = {change.Account.Nonce.ToHexString(skipLeadingZeros: true)} C = {change.Account.CodeHash}");
   690→
   691→            [MethodImpl(MethodImplOptions.NoInlining)]
   692→            void TraceRemoveEmpty(in Change change)
   693→                => _logger.Trace($"Commit remove empty {change.Address} B = {change.Account.Balance.ToHexString(skipLeadingZeros: true)} N = {change.Account.Nonce.ToHexString(skipLeadingZeros: true)}");
   694→
   695→            [DoesNotReturn, StackTraceHidden]
   696→            static void ThrowStartOfCommitIsNull(int currentPosition)
   697→                => throw new InvalidOperationException($"Change at current position {currentPosition} was null when committing {nameof(StateProvider)}");
   698→
   699→            [DoesNotReturn, StackTraceHidden]
   700→            static void ThrowUnknownChangeType() => throw new ArgumentOutOfRangeException();
   701→
   702→            [DoesNotReturn, StackTraceHidden]
   703→            static void ThrowUnexpectedPosition(int currentPosition, int i, int forAssertion)
   704→                => throw new InvalidOperationException($"Expected checked value {forAssertion} to be equal to {currentPosition} - {i}");
   705→        }
   706→
   707→        private void FlushToTree()
   708→        {
   709→            int writes = 0;
   710→            int skipped = 0;
   711→
   712→            using ArrayPoolList<PatriciaTree.BulkSetEntry> bulkWrite = new(_blockChanges.Count);
   713→            foreach (var key in _blockChanges.Keys)
   714→            {
   715→                ref var change = ref CollectionsMarshal.GetValueRefOrNullRef(_blockChanges, key);
   716→                if (change.Before != change.After)
   717→                {
   718→                    change.Before = change.After;
   719→
   720→                    KeccakCache.ComputeTo(key.Value.Bytes, out ValueHash256 keccak);
   721→
   722→                    var account = change.After;
   723→                    Rlp accountRlp = account is null ? null : account.IsTotallyEmpty ? StateTree.EmptyAccountRlp : Rlp.Encode(account);
   724→
   725→                    bulkWrite.Add(new PatriciaTree.BulkSetEntry(keccak, accountRlp?.Bytes));
   726→                    writes++;
   727→                }
   728→                else
   729→                {
   730→                    skipped++;
   731→                }
   732→            }
   733→
   734→            _tree.BulkSet(bulkWrite);
   735→
   736→            if (writes > 0)
   737→                Metrics.IncrementStateTreeWrites(writes);
   738→            if (skipped > 0)
   739→                Metrics.IncrementStateSkippedWrites(skipped);
   740→        }
   741→
   742→        public bool WarmUp(Address address)
   743→            => GetState(address) is not null;
   744→
   745→        private Account? GetState(Address address)
   746→        {
   747→            AddressAsKey addressAsKey = address;
   748→            ref ChangeTrace accountChanges = ref CollectionsMarshal.GetValueRefOrAddDefault(_blockChanges, addressAsKey, out bool exists);
   749→            if (!exists)
   750→            {
   751→                Account? account = !_populatePreBlockCache ?
   752→                    GetStateReadPreWarmCache(addressAsKey) :
   753→                    GetStatePopulatePrewarmCache(addressAsKey);
   754→
   755→                accountChanges = new(account, account);
   756→            }
   757→            else
   758→            {
   759→                Metrics.IncrementStateTreeCacheHits();
   760→            }
   761→            return accountChanges.After;
   762→        }
   763→
   764→        private Account? GetStatePopulatePrewarmCache(AddressAsKey addressAsKey)
   765→        {
   766→            long priorReads = Metrics.ThreadLocalStateTreeReads;
   767→            Account? account = _preBlockCache is not null
   768→                ? _preBlockCache.GetOrAdd(addressAsKey, _getStateFromTrie)
   769→                : _getStateFromTrie(addressAsKey);
   770→
   771→            if (Metrics.ThreadLocalStateTreeReads == priorReads)
   772→            {
   773→                Metrics.IncrementStateTreeCacheHits();
   774→            }
   775→            return account;
   776→        }
   777→
   778→        private Account? GetStateReadPreWarmCache(AddressAsKey addressAsKey)
   779→        {
   780→            if (_preBlockCache?.TryGetValue(addressAsKey, out Account? account) ?? false)
   781→            {
   782→                Metrics.IncrementStateTreeCacheHits();
   783→            }
   784→            else
   785→            {
   786→                account = _getStateFromTrie(addressAsKey);
   787→            }
   788→            return account;
   789→        }
   790→
   791→        private void SetState(Address address, Account? account)
   792→        {
   793→            ref ChangeTrace accountChanges = ref CollectionsMarshal.GetValueRefOrAddDefault(_blockChanges, address, out _);
   794→            accountChanges.After = account;
   795→            _needsStateRootUpdate = true;
   796→        }
   797→
   798→        private Account? GetAndAddToCache(Address address)
   799→        {
   800→            if (_nullAccountReads.Contains(address)) return null;
   801→
   802→            Account? account = GetState(address);
   803→            if (account is not null)
   804→            {
   805→                PushJustCache(address, account);
   806→            }
   807→            else
   808→            {
   809→                // just for tracing - potential perf hit, maybe a better solution?
   810→                _nullAccountReads.Add(address);
   811→            }
   812→
   813→            return account;
   814→        }
   815→
   816→        private Account? GetThroughCache(Address address)
   817→        {
   818→            if (_intraTxCache.TryGetValue(address, out Stack<int> value))
   819→            {
   820→                return _changes[value.Peek()].Account;
   821→            }
   822→
   823→            Account account = GetAndAddToCache(address);
   824→            return account;
   825→        }
   826→
   827→        private void PushJustCache(Address address, Account account)
   828→            => Push(address, account, ChangeType.JustCache);
   829→
   830→        private void PushUpdate(Address address, Account account)
   831→            => Push(address, account, ChangeType.Update);
   832→
   833→        private void PushTouch(Address address, Account account, IReleaseSpec releaseSpec, bool isZero)
   834→        {
   835→            if (isZero && releaseSpec.IsEip158IgnoredAccount(address)) return;
   836→            Push(address, account, ChangeType.Touch);
   837→        }
   838→
   839→        private void PushDelete(Address address)
   840→            => Push(address, null, ChangeType.Delete);
   841→
   842→        private void Push(Address address, Account? touchedAccount, ChangeType changeType)
   843→        {
   844→            Stack<int> stack = SetupCache(address);
   845→            if (changeType == ChangeType.Touch
   846→                && _changes[stack.Peek()]!.ChangeType == ChangeType.Touch)
   847→            {
   848→                return;
   849→            }
   850→
   851→            stack.Push(_changes.Count);
   852→            _changes.Add(new Change(address, touchedAccount, changeType));
   853→        }
   854→
   855→        private void PushNew(Address address, Account account)
   856→        {
   857→            Stack<int> stack = SetupCache(address);
   858→            stack.Push(_changes.Count);
   859→            _changes.Add(new Change(address, account, ChangeType.New));
   860→        }
   861→
   862→        private Stack<int> SetupCache(Address address)
   863→        {
   864→            ref Stack<int>? value = ref CollectionsMarshal.GetValueRefOrAddDefault(_intraTxCache, address, out bool exists);
   865→            if (!exists)
   866→            {
   867→                value = new Stack<int>();
   868→            }
   869→
   870→            return value;
   871→        }
   872→
   873→        public ArrayPoolList<AddressAsKey>? ChangedAddresses()
   874→        {
   875→            int count = _blockChanges.Count;
   876→            if (count == 0)
   877→            {
   878→                return null;
   879→            }
   880→            else
   881→            {
   882→                ArrayPoolList<AddressAsKey> addresses = new(count);
   883→                foreach (AddressAsKey address in _blockChanges.Keys)
   884→                {
   885→                    addresses.Add(address);
   886→                }
   887→                return addresses;
   888→            }
   889→        }
   890→
   891→        public void Reset(bool resetBlockChanges = true)
   892→        {
   893→            if (_logger.IsTrace) Trace();
   894→            if (resetBlockChanges)
   895→            {
   896→                _blockChanges.Clear();
   897→                _codeBatch?.Clear();
   898→            }
   899→            _intraTxCache.Clear();
   900→            _committedThisRound.Clear();
   901→            _nullAccountReads.Clear();
   902→            _changes.Clear();
   903→            _needsStateRootUpdate = false;
   904→
   905→            [MethodImpl(MethodImplOptions.NoInlining)]
   906→            void Trace() => _logger.Trace("Clearing state provider caches");
   907→        }
   908→
   909→        public void CommitTree()
   910→        {
   911→            if (_needsStateRootUpdate)
   912→            {
   913→                RecalculateStateRoot();
   914→            }
   915→
   916→            _tree.Commit();
   917→        }
   918→
   919→        // used in EthereumTests
   920→        internal void SetNonce(Address address, in UInt256 nonce)
   921→        {
   922→            _needsStateRootUpdate = true;
   923→            Account account = GetThroughCache(address) ?? ThrowNullAccount(address);
   924→            Account changedAccount = account.WithChangedNonce(nonce);
   925→            if (_logger.IsTrace) Trace(address, account, changedAccount);
   926→
   927→            PushUpdate(address, changedAccount);
   928→
   929→            [MethodImpl(MethodImplOptions.NoInlining)]
   930→            void Trace(Address address, Account account, Account changedAccount)
   931→                => _logger.Trace($"Update {address} N {account.Nonce} -> {changedAccount.Nonce}");
   932→
   933→            [DoesNotReturn, StackTraceHidden]
   934→            static Account ThrowNullAccount(Address address)
   935→                => throw new InvalidOperationException($"Account {address} is null when incrementing nonce");
   936→        }
   937→
   938→        private enum ChangeType
   939→        {
   940→            Null = 0,
   941→            JustCache,
   942→            Touch,
   943→            Update,
   944→            New,
   945→            Delete
   946→        }
   947→
   948→        private readonly struct Change(Address address, Account? account, ChangeType type)
   949→        {
   950→            public readonly Address Address = address;
   951→            public readonly Account? Account = account;
   952→            public readonly ChangeType ChangeType = type;
   953→
   954→            public bool IsNull => ChangeType == ChangeType.Null;
   955→        }
   956→
   957→        internal struct ChangeTrace(Account? before, Account? after)
   958→        {
   959→            public ChangeTrace(Account? after) : this(null, after)
   960→            {
   961→            }
   962→
   963→            public Account? Before { get; set; } = before;
   964→            public Account? After { get; set; } = after;
   965→        }
   966→    }
   967→
   968→    internal static class Extensions
   969→    {
   970→        [MethodImpl(MethodImplOptions.NoInlining)]
   971→        public static void AddToTrace(this Dictionary<AddressAsKey, ChangeTrace> trace, Address address, Account? change)
   972→        {
   973→            trace.Add(address, new ChangeTrace(change));
   974→        }
   975→
   976→        [MethodImpl(MethodImplOptions.NoInlining)]
   977→        public static void UpdateTrace(this Dictionary<AddressAsKey, ChangeTrace> trace, Address address, Account? change)
   978→        {
   979→            trace[address] = new ChangeTrace(change, trace[address].After);
   980→        }
   981→
   982→        [MethodImpl(MethodImplOptions.NoInlining)]
   983→        public static void ReportStateTrace(this Dictionary<AddressAsKey, ChangeTrace>? trace, IWorldStateTracer stateTracer, HashSet<AddressAsKey> nullAccountReads, StateProvider stateProvider)
   984→        {
   985→            foreach (Address nullRead in nullAccountReads)
   986→            {
   987→                // // this may be enough, let us write tests
   988→                stateTracer.ReportAccountRead(nullRead);
   989→            }
   990→            ReportChanges(trace, stateTracer, stateProvider);
   991→        }
   992→
   993→        private static void ReportChanges(Dictionary<AddressAsKey, ChangeTrace> trace, IStateTracer stateTracer, StateProvider stateProvider)
   994→        {
   995→            foreach ((Address address, ChangeTrace change) in trace)
   996→            {
   997→                bool someChangeReported = false;
   998→
   999→                Account? before = change.Before;
  1000→                Account? after = change.After;
  1001→
  1002→                UInt256? beforeBalance = before?.Balance;
  1003→                UInt256? afterBalance = after?.Balance;
  1004→
  1005→                UInt256? beforeNonce = before?.Nonce;
  1006→                UInt256? afterNonce = after?.Nonce;
  1007→
  1008→                Hash256? beforeCodeHash = before?.CodeHash;
  1009→                Hash256? afterCodeHash = after?.CodeHash;
  1010→
  1011→                if (beforeCodeHash != afterCodeHash)
  1012→                {
  1013→                    byte[]? beforeCode = beforeCodeHash is null
  1014→                        ? null
  1015→                        : beforeCodeHash == Keccak.OfAnEmptyString
  1016→                            ? []
  1017→                            : stateProvider.GetCode(in beforeCodeHash.ValueHash256);
  1018→                    byte[]? afterCode = afterCodeHash is null
  1019→                        ? null
  1020→                        : afterCodeHash == Keccak.OfAnEmptyString
  1021→                            ? []
  1022→                            : stateProvider.GetCode(in afterCodeHash.ValueHash256);
  1023→
  1024→                    if (!((beforeCode?.Length ?? 0) == 0 && (afterCode?.Length ?? 0) == 0))
  1025→                    {
  1026→                        stateTracer.ReportCodeChange(address, beforeCode, afterCode);
  1027→                    }
  1028→
  1029→                    someChangeReported = true;
  1030→                }
  1031→
  1032→                if (afterBalance != beforeBalance)
  1033→                {
  1034→                    stateTracer.ReportBalanceChange(address, beforeBalance, afterBalance);
  1035→                    someChangeReported = true;
  1036→                }
  1037→
  1038→                if (afterNonce != beforeNonce)
  1039→                {
  1040→                    stateTracer.ReportNonceChange(address, beforeNonce, afterNonce);
  1041→                    someChangeReported = true;
  1042→                }
  1043→
  1044→                if (!someChangeReported)
  1045→                {
  1046→                    stateTracer.ReportAccountRead(address);
  1047→                }
  1048→            }
  1049→        }
  1050→    }
  1051→}
